<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';$error=null;$f=[];$user=[];$p=bi_step22_period($_GET['month']??null);
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.view');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];$f=bi_step22_funnel($pdo,$orgId,$p['start'],$p['end']);$stageRows=$pdo->prepare("SELECT stage,COUNT(*) cnt FROM crm_leads WHERE organization_id=? AND created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY stage ORDER BY cnt DESC");$stageRows->execute([$orgId,$p['start'],$p['end']]);$stages=$stageRows->fetchAll();$typeRows=$pdo->prepare("SELECT lead_type,COUNT(*) cnt FROM crm_leads WHERE organization_id=? AND created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY lead_type ORDER BY cnt DESC");$typeRows->execute([$orgId,$p['start'],$p['end']]);$types=$typeRows->fetchAll();}catch(Throwable $e){$error=$e->getMessage();$stages=[];$types=[];}
