?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead Funnel - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="executive_bi.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • Lead Funnel</small></span></a><div class="os-top-actions"><a class="os-btn" href="lead_center.php">Lead CRM</a><a class="os-btn primary" href="executive_bi.php">Executive BI</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">LEAD & CONVERSION INTELLIGENCE • <?=bi_step22_h($p['label'])?></div><h1>See how website enquiries move into real Customer or Member conversions.</h1><p>Accepted submissions, Leads and explicit conversion evidence remain separate. Appointment requests are not counted as conversions.</p></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php else:?><section class="os-card" style="margin-top:14px"><form method="get" style="display:flex;gap:8px;align-items:end"><div><label class="bi-muted">Month</label><input type="month" name="month" value="<?=bi_step22_h($p['key'])?>" style="display:block;padding:9px;border:1px solid #d8dfda;border-radius:10px"></div><button class="os-btn">Apply</button></form></section><section class="bi-funnel" style="margin-top:14px"><div><small>Accepted Submissions</small><strong><?=$f['submissions']?></strong></div><div><small>Unique Leads</small><strong><?=$f['leads']?></strong></div><div><small>Contacted</small><strong><?=$f['contacted']?></strong></div><div><small>Qualified</small><strong><?=$f['qualified']?></strong></div><div><small>Appointment Stage</small><strong><?=$f['appointment']?></strong></div><div><small>Converted</small><strong><?=$f['converted']?></strong></div></section><section class="bi-grid" style="margin-top:14px"><article class="os-card bi-span-6"><h2>Lead Stage Mix</h2><div class="bi-bars"><?php foreach($stages as $r):$w=min(100,(int)$r['cnt']/$leadBase*100);?><div class="bi-bar-row"><span><?=bi_step22_h(ucfirst((string)$r['stage']))?></span><div class="bi-bar-track"><div class="bi-bar-fill" style="width:<?=$w?>%"></div></div><strong><?=$r['cnt']?></strong></div><?php endforeach;?><?php if(!$stages):?><div class="bi-note">No leads created in this month.</div><?php endif;?></div></article><article class="os-card bi-span-6"><h2>Enquiry Type Mix</h2><div class="bi-bars"><?php foreach($types as $r):$w=min(100,(int)$r['cnt']/$leadBase*100);?><div class="bi-bar-row"><span><?=bi_step22_h(ucfirst((string)$r['lead_type']))?></span><div class="bi-bar-track"><div class="bi-bar-fill" style="width:<?=$w?>%"></div></div><strong><?=$r['cnt']?></strong></div><?php endforeach;?><?php if(!$types):?><div class="bi-note">No enquiry type data for this month.</div><?php endif;?></div></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Funnel Notes</h2><p>Counts are factual, not modeled probabilities.</p></div></div><div class="bi-pills"><span class="bi-pill">Lead conversion rate: <?=$f['leads']>0?number_format($f['converted']/$f['leads']*100,1).'%':'N/A'?></span><span class="bi-pill">Lost: <?=$f['lost']?></span><span class="bi-pill">Appointment is a stage, not a sale</span><span class="bi-pill">Conversion requires Customer/Member evidence</span></div></article></section><?php endif;?></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
